BEGIN;
CREATE TABLE IF NOT EXISTS travel_users(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,birth_date DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS travel_tenants(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS travel_memberships(tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),user_id BIGINT NOT NULL REFERENCES travel_users(id),role TEXT NOT NULL CHECK(role IN('traveler','planner','guardian','booking_operator','privacy_officer','auditor','admin')),active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS travel_preference_versions(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),subject_id BIGINT NOT NULL REFERENCES travel_users(id),version_ref TEXT NOT NULL,preferences JSONB NOT NULL,preferences_digest CHAR(64) NOT NULL,created_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,subject_id,version_ref),UNIQUE(tenant_id,preferences_digest));
CREATE TABLE IF NOT EXISTS travel_trips(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),subject_id BIGINT NOT NULL REFERENCES travel_users(id),preference_version_id BIGINT NOT NULL REFERENCES travel_preference_versions(id),title TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN('draft','planned','editing','review_pending','approved','booking_queued','booking_failed','booked','in_progress','cancel_queued','cancelled','completed')),revision INTEGER NOT NULL DEFAULT 1,created_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS travel_itinerary_versions(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT NOT NULL REFERENCES travel_trips(id),parent_version_id BIGINT REFERENCES travel_itinerary_versions(id),version_ref TEXT NOT NULL,itinerary JSONB NOT NULL,itinerary_digest CHAR(64) NOT NULL,edit_reason TEXT NOT NULL,created_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,trip_id,version_ref),UNIQUE(tenant_id,itinerary_digest));
CREATE TABLE IF NOT EXISTS travel_evaluations(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),itinerary_version_id BIGINT NOT NULL REFERENCES travel_itinerary_versions(id),evaluation JSONB NOT NULL,evaluation_digest CHAR(64) NOT NULL,passed BOOLEAN NOT NULL,evaluated_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,itinerary_version_id,evaluation_digest));
CREATE TABLE IF NOT EXISTS travel_feedback(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT NOT NULL REFERENCES travel_trips(id),itinerary_version_id BIGINT NOT NULL REFERENCES travel_itinerary_versions(id),feedback JSONB NOT NULL,feedback_digest CHAR(64) NOT NULL,created_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,trip_id,feedback_digest));
CREATE TABLE IF NOT EXISTS travel_integrations(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),subject_id BIGINT NOT NULL REFERENCES travel_users(id),provider TEXT NOT NULL,consent JSONB NOT NULL,consent_digest CHAR(64) NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked','deletion_pending','deleted')),created_by BIGINT NOT NULL REFERENCES travel_users(id),revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,subject_id,provider,consent_digest));
CREATE TABLE IF NOT EXISTS travel_booking_searches(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT NOT NULL REFERENCES travel_trips(id),provider TEXT NOT NULL,request JSONB NOT NULL,request_digest CHAR(64) NOT NULL,idempotency_key TEXT NOT NULL,result_count INTEGER NOT NULL CHECK(result_count>=0),searched_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS travel_booking_quotes(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT NOT NULL REFERENCES travel_trips(id),search_id BIGINT NOT NULL REFERENCES travel_booking_searches(id),quote JSONB NOT NULL,quote_digest CHAR(64) NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,quote_digest));
CREATE TABLE IF NOT EXISTS travel_booking_approvals(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT NOT NULL REFERENCES travel_trips(id),quote_id BIGINT NOT NULL REFERENCES travel_booking_quotes(id),approval JSONB NOT NULL,approval_digest CHAR(64) NOT NULL,approved_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,trip_id,approval_digest));
CREATE TABLE IF NOT EXISTS travel_booking_outbox(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT NOT NULL REFERENCES travel_trips(id),approval_id BIGINT NOT NULL REFERENCES travel_booking_approvals(id),operation TEXT NOT NULL CHECK(operation IN('reserve','cancel')),idempotency_key TEXT NOT NULL,payload JSONB NOT NULL,payload_digest CHAR(64) NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','processing','retry','succeeded','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),external_reservation_ref TEXT,evidence_digest CHAR(64),last_error_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS travel_provider_receipts(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT REFERENCES travel_trips(id),provider TEXT NOT NULL,operation TEXT NOT NULL,external_ref TEXT NOT NULL,receipt JSONB NOT NULL,receipt_digest CHAR(64) NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,external_ref,receipt_digest));
CREATE TABLE IF NOT EXISTS travel_exports(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),subject_id BIGINT NOT NULL REFERENCES travel_users(id),manifest JSONB NOT NULL,manifest_digest CHAR(64) NOT NULL,exported_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,subject_id,manifest_digest));
CREATE TABLE IF NOT EXISTS travel_deletion_requests(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),subject_id BIGINT NOT NULL REFERENCES travel_users(id),request_ref TEXT NOT NULL,plan JSONB NOT NULL,plan_digest CHAR(64) NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','propagating','completed','blocked')),requested_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),completed_at TIMESTAMPTZ,UNIQUE(tenant_id,request_ref));
CREATE TABLE IF NOT EXISTS travel_deletion_receipts(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),deletion_request_id BIGINT NOT NULL REFERENCES travel_deletion_requests(id),provider TEXT NOT NULL,external_ref TEXT NOT NULL,receipt_digest CHAR(64) NOT NULL,deleted_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,deletion_request_id,provider));
CREATE TABLE IF NOT EXISTS travel_provider_usage(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),provider TEXT NOT NULL,operation TEXT NOT NULL,usage JSONB NOT NULL,usage_digest CHAR(64) NOT NULL,evidence_digest CHAR(64) NOT NULL,recorded_by BIGINT NOT NULL REFERENCES travel_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,usage_digest));
CREATE TABLE IF NOT EXISTS travel_provider_failures(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT REFERENCES travel_trips(id),provider TEXT NOT NULL,operation TEXT NOT NULL,error_code TEXT NOT NULL,retryable BOOLEAN NOT NULL,sanitized_detail TEXT NOT NULL DEFAULT 'provider detail redacted',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS travel_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES travel_tenants(id),trip_id BIGINT REFERENCES travel_trips(id),actor_id BIGINT REFERENCES travel_users(id),event_type TEXT NOT NULL,payload JSONB NOT NULL,evidence_digest CHAR(64),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS travel_booking_ready_idx ON travel_booking_outbox(status,next_attempt_at);CREATE INDEX IF NOT EXISTS travel_trip_state_idx ON travel_trips(tenant_id,state,updated_at);
CREATE OR REPLACE FUNCTION prevent_travel_evidence_mutation() RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'travel evidence is append-only';END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_travel_booking_request() RETURNS trigger AS $$BEGIN IF OLD.tenant_id<>NEW.tenant_id OR OLD.trip_id<>NEW.trip_id OR OLD.approval_id<>NEW.approval_id OR OLD.operation<>NEW.operation OR OLD.idempotency_key<>NEW.idempotency_key OR OLD.payload IS DISTINCT FROM NEW.payload OR OLD.payload_digest<>NEW.payload_digest OR OLD.created_at<>NEW.created_at THEN RAISE EXCEPTION 'booking request evidence is immutable';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['travel_preference_versions','travel_itinerary_versions','travel_evaluations','travel_feedback','travel_booking_searches','travel_booking_quotes','travel_booking_approvals','travel_provider_receipts','travel_exports','travel_deletion_receipts','travel_provider_usage','travel_audit_events'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_append_only ON %I',t,t);EXECUTE format('CREATE TRIGGER %I_append_only BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_travel_evidence_mutation()',t,t);END LOOP;END$$;
DROP TRIGGER IF EXISTS travel_booking_request_guard ON travel_booking_outbox;CREATE TRIGGER travel_booking_request_guard BEFORE UPDATE ON travel_booking_outbox FOR EACH ROW EXECUTE FUNCTION guard_travel_booking_request();
COMMIT;
